#!/usr/bin/env python3
"""Extrai somente o código do aplicativo. Não contém planilha ou dados pessoais.

Requer Python 3.10+. Use --dest para escolher uma pasta NOVA para o aplicativo.
Leia o README extraído para instalar dependências e importar sua planilha local.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import io
from pathlib import Path, PurePosixPath
import stat
import sys
import tempfile
import zipfile

PAYLOAD_SHA256 = "533b22f6a5d5d8ab7b156eece0e1cd75bf632448f3b30227ade311cca1241c1b"
PAYLOAD_BASE64 = ""


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--dest', type=Path, default=Path.cwd() / 'financas-local')
    args = parser.parse_args()
    if sys.version_info < (3, 10):
        parser.error('Use Python 3.10 ou superior.')
    target = args.dest.expanduser().absolute()
    if target.exists() or target.is_symlink():
        parser.error('A pasta de destino já existe. Escolha outra para preservar seus arquivos.')
    raw = base64.b64decode(PAYLOAD_BASE64, validate=True)
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        parser.error('O código não passou na verificação de integridade.')
    target.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='.financas-install-', dir=target.parent) as temporary:
        stage = Path(temporary) / 'app'
        stage.mkdir()
        with zipfile.ZipFile(io.BytesIO(raw)) as archive:
            for item in archive.infolist():
                path = PurePosixPath(item.filename)
                if path.is_absolute() or '..' in path.parts or '\\' in item.filename:
                    parser.error('O pacote contém um caminho inválido.')
                if stat.S_ISLNK(item.external_attr >> 16):
                    parser.error('O pacote contém um vínculo simbólico inválido.')
            archive.extractall(stage)
        for name in ('iniciar_macos.command', 'iniciar_linux.sh'):
            (stage / name).chmod(0o755)
        if target.exists() or target.is_symlink():
            parser.error('A pasta de destino já existe; nenhum arquivo foi substituído.')
        stage.rename(target)
    print('Código extraído em:', target)
    print('Leia README.md para instalar as dependências e importar sua planilha local.')


if __name__ == '__main__':
    main()
